<template>
  <div class="app-container agent-page">
    <div class="page-heading"><div><h2>成本与预算</h2><p>查看 Agent 任务预算、实际消耗、超预算和未计价信号。</p></div><el-tag type="info" effect="plain">只读汇总</el-tag></div>
    <el-row :gutter="14" class="summary-row"><el-col :xs="24" :sm="12" :lg="4" v-for="item in summaryCards" :key="item.key"><el-card shadow="never" class="summary-card"><div class="summary-label">{{ item.label }}</div><div class="summary-value" :class="item.tone">{{ item.value }}</div></el-card></el-col></el-row>
    <el-alert v-if="dailyLimits.enforced" class="daily-budget-alert" :title="`今日平台配额：${dailyUsage.taskCount || 0} / ${dailyLimits.maxTasks || '不限'} 个任务，${dailyUsage.tokenUsage || 0} / ${dailyLimits.maxTokens || '不限'} Token，$${money(dailyUsage.costUsage)} / ${dailyLimits.maxCost ? `$${money(dailyLimits.maxCost)}` : '不限'}`" type="info" :closable="false" show-icon />
    <el-card shadow="never">
      <el-form :inline="true" class="toolbar"><el-form-item><el-select v-model="query.taskType" placeholder="任务类型" clearable style="width: 170px" @change="load"><el-option v-for="item in taskTypes" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-select v-model="query.status" placeholder="状态" clearable style="width: 150px" @change="load"><el-option v-for="item in statuses" :key="item" :label="item" :value="item" /></el-select></el-form-item><el-form-item><el-select v-model="query.overBudget" placeholder="预算状态" clearable style="width: 150px" @change="load"><el-option label="已超预算" :value="true" /><el-option label="未超预算" :value="false" /></el-select></el-form-item><el-form-item><el-select v-if="tenantScopes.length" v-model="query.tenantKey" placeholder="授权租户" clearable style="width: 190px" @change="load"><el-option v-for="scope in tenantScopes" :key="scope.tenantKey" :label="scope.tenantKey" :value="scope.tenantKey" /></el-select><el-input v-else v-model="query.tenantKey" placeholder="租户 Key" clearable style="width: 170px" @keyup.enter="load" /></el-form-item><el-button type="primary" :loading="loading" @click="load">刷新</el-button></el-form>
      <el-table v-loading="loading" :data="rows" empty-text="暂无预算数据"><el-table-column prop="taskKey" label="任务" min-width="180" /><el-table-column prop="taskType" label="类型" width="160" /><el-table-column prop="status" label="状态" width="140" /><el-table-column label="Token 使用" min-width="180"><template #default="{ row }">{{ row.tokenUsage || 0 }} / {{ row.maxTokens || '不限' }}</template></el-table-column><el-table-column label="费用使用" min-width="160"><template #default="{ row }">${{ money(row.costAmount) }} / {{ row.maxCost ? `$${money(row.maxCost)}` : '不限' }}</template></el-table-column><el-table-column label="预算状态" width="110"><template #default="{ row }"><el-tag :type="row.overBudget ? 'danger' : 'success'">{{ row.overBudget ? '超预算' : '正常' }}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="180" /></el-table>
      <pagination v-show="total > 0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
    </el-card>
  </div>
</template>
<script setup name="JgAgentBudget">
import { getAgentBudget, listMyAgentTenantScopes } from '@/api/jiugai/agentConfig'
const loading = ref(false); const rows = ref([]); const total = ref(0); const summary = ref({}); const dailyUsage = ref({}); const dailyLimits = ref({}); const query = reactive({ pageNum: 1, pageSize: 20, taskType: undefined, status: undefined, overBudget: undefined, tenantKey: undefined }); const tenantScopes = ref([]); const taskTypes = ['CONTENT_CREATION', 'GENERAL', 'OPERATIONS_REVIEW']; const statuses = ['RUNNING', 'WAITING_APPROVAL', 'SUCCEEDED', 'PARTIAL_SUCCESS', 'FAILED', 'CANCELLED']
const summaryCards = computed(() => [{ key: 'taskCount', label: '任务数', value: summary.value.taskCount || 0 }, { key: 'tokenUsage', label: 'Token 使用', value: summary.value.tokenUsage || 0 }, { key: 'tokenBudget', label: 'Token 预算', value: summary.value.tokenBudget || 0 }, { key: 'costUsage', label: '费用使用', value: `$${money(summary.value.costUsage)}` }, { key: 'overBudgetTasks', label: '超预算任务', value: summary.value.overBudgetTasks || 0, tone: summary.value.overBudgetTasks ? 'danger' : '' }, { key: 'unpricedTasks', label: '未计价任务', value: summary.value.unpricedTasks || 0, tone: summary.value.unpricedTasks ? 'warning' : '' }])
function money(value) { const number = Number(value || 0); return Number.isFinite(number) ? number.toFixed(6) : '0.000000' }
async function load() { loading.value = true; try { const response = await getAgentBudget(query); const data = response.data || {}; summary.value = data.summary || {}; dailyUsage.value = data.dailyBudgetUsage || {}; dailyLimits.value = data.dailyBudgetLimits || {}; rows.value = data.rows || []; total.value = data.total || 0 } finally { loading.value = false } }
async function loadTenantScopes() { try { const response = await listMyAgentTenantScopes(); tenantScopes.value = Array.isArray(response) ? response : (response.data || []); if (tenantScopes.value.length && !query.tenantKey) query.tenantKey = tenantScopes.value[0].tenantKey } catch (e) { tenantScopes.value = [] } }
onMounted(async () => { await loadTenantScopes(); await load() })
</script>
<style scoped>
.agent-page { color: #1f2937; }.page-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 18px; }.page-heading h2 { margin: 0 0 6px; font-size: 22px; }.page-heading p { margin: 0; color: #6b7280; }.summary-row { margin-bottom: 14px; }.summary-card { min-height: 92px; }.summary-label { color: #6b7280; font-size: 13px; }.summary-value { margin-top: 10px; color: #1f2937; font-size: 22px; font-weight: 600; }.summary-value.danger { color: #dc2626; }.summary-value.warning { color: #d97706; }.daily-budget-alert { margin-bottom: 14px; }.toolbar { margin-bottom: 6px; }
</style>
